def extend(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(text='El Barroco español\n«Barroco español» es un concepto de la historiografía del arte, de la literatura y de la música para clasificar las manifestaciones culturales de la época, aproximadamente el siglo y medio entre 1600 y 1750, localizadas en España. Se aplica sobre todo a las producciones de la Corte; no suelen englobarse bajo el término ni el Barroco portugués, ni el italiano de Nápoles o Sicilia, ni el colonial americano. La fuente señala también las críticas que se le han hecho: el exceso ornamental y el contexto de decadencia política y económica y de tensiones religiosas, que habría influido en el tono melancólico y sombrío de muchas obras. La fuente inglesa precisa que la fase política del Siglo de Oro suele darse por terminada en 1659 con el Tratado de los Pirineos, aunque en términos culturales se prolonga hasta 1681, año de la muerte de Calderón.',
        quotes=[Q('es_barroco', 'se utiliza para clasificar y definir las manifestaciones culturales de la época del Barroco'), Q('es_barroco', 'estuvo marcado por un contexto histórico de decadencia política y económica'), Q('en_golden_age', 'although the period is commonly understood to have continued in cultural terms until 1681, the year of Pedro Calderón de la Barca\'s death'), Q('es_siglo_oro', 'Siglo de Oro')]))
    P.append(dict(text='El corral de comedias\nLa comedia nueva necesitaba un lugar: el corral de comedias, teatro público permanente instalado al descubierto en los patios interiores de las casas. Antes de la década de 1560 no existía en España el concepto de edificio dedicado al teatro, y las funciones se daban en palacios, iglesias, plazas y patios. El espacio se organizaba con un tablado al fondo, gradas y galerías laterales, aposentos para la nobleza y un patio de pie. En Madrid había seis corrales a fines del siglo XVI, entre ellos el de la Cruz y el del Príncipe, que dependían de cofradías de beneficencia que financiaban sus obras con las representaciones. El único corral completo que se conserva es el de Almagro. Se llamaban «comedias» todas las obras profanas, aunque fueran tragedias o dramas.',
        quotes=[Q('es_corral', 'Antes de la década de 1560 no existía en España el concepto de edificio dedicado a la representación de teatro.'), Q('es_corral', 'un tablado para albergar el escenario dispuesto en el fondo del patio'), Q('es_corral', 'En el último cuarto del siglo XVI había seis corrales abiertos en la capital española'), Q('es_corral', 'el único completo es el de Almagro'), Q('es_arte_nuevo', 'Arte nuevo de hacer comedias')]))
    P.append(dict(text='Un arte para el vulgo\nEl Arte nuevo se abre como una respuesta a una petición de los ingenios de la Academia: que escriba «un arte de comedias» que «al estilo del vulgo se reciba». Lope confiesa que su culpa es haberlas escrito «sin el arte», aunque no por ignorar los preceptos, sino porque encontró que las comedias de España no eran como las concibieron sus primeros inventores, sino como las trataron «muchos bárbaros que enseñaron el vulgo a sus rudezas». Quien las escribe con arte, dice, «muere sin fama y galardón». Por eso, cuando ha de escribir una comedia, «encierro los preceptos con seis llaves, saco a Terencio y Plauto de mi estudio». La fuente inglesa lo resume: era su manifiesto artístico y la justificación de su estilo, que rompía las tres unidades neoclásicas de lugar, tiempo y acción.',
        quotes=[Q('ws_arte_nuevo', 'que un arte de comedias os escriba', 'que al estilo del vulgo se reciba.'), Q('ws_arte_nuevo', 'es haberlas escrito sin el arte.'), Q('ws_arte_nuevo', 'encierro los preceptos con seis llaves,', 'saco a Terencio y Plauto de mi estudio'), Q('en_lope', 'which broke the neoclassical three unities of place, time and action')]))
    P.append(dict(text='Un soneto sobre hacer un soneto\nEl soneto «Un soneto me manda hacer Violante» es una broma metapoética: el poeta cuenta cómo construye el poema que está escribiendo. Los cuartetos presentan el apuro («que en mi vida me he visto en tanto aprieto») y la dificultad de encontrar el consonante; los tercetos avanzan verso a verso hasta el final: «contad si son catorce, y está hecho». La fuente en español usa el poema como ejemplo del soneto de Lope que trata de la construcción de un soneto. El humor reside en que el contenido del poema coincide con su forma: cada verso describe el verso que se escribe. Es un modelo del juego conceptista barroco, que Lope cultivó en los 3000 sonetos que, según la fuente inglesa, compuso.',
        quotes=[Q('ws_lope_soneto', 'Un soneto me manda hacer Violante,'), Q('ws_lope_soneto', 'contad si son catorce, y está hecho.'), Q('es_soneto', 'Un ejemplo conocido es el siguiente soneto de Lope de Vega, que trata precisamente sobre la construcción de un soneto'), Q('en_lope', 'The literary production of Lope de Vega includes 3,000 sonnets')]))
    P.append(dict(text='Fuenteovejuna\nFuenteovejuna es un drama «municipal» de Lope, compuesto en tres actos hacia 1612-1614 y publicado en Madrid en 1619 en la Dozena parte de sus comedias. Toma su argumento de un hecho real ocurrido en Fuente Obejuna, en tiempos de los Reyes Católicos, y tiene un protagonista colectivo: los habitantes del pueblo. Lope la escribió bajo el mecenazgo de Pedro Téllez Girón y quiso ensalzar a los Girón, de ahí la alusión a Rodrigo Téllez Girón, maestre de Calatrava. La lectura básica es que el pueblo no busca cambiar el sistema social, solo justicia, y confía en que la autoridad real avale su acción. Algunos analistas ven, además, un fondo político: la lucha entre los partidarios de Juana la Beltraneja y los de Isabel la Católica.',
        quotes=[Q('es_fuenteovejuna', 'Fue compuesta en tres actos hacia 1612-1614 y publicada en Madrid en 1619'), Q('es_fuenteovejuna', 'El drama se presenta con un protagonista colectivo (los habitantes del pueblo)'), Q('es_fuenteovejuna', 'La tesis elemental es que el pueblo no busca cambiar el sistema social, tan solo quiere justicia'), Q('es_fuenteovejuna', 'la rebelión tiene como fondo la lucha del partido de Juana la Beltraneja con los partidarios de Isabel la Católica'), Q('es_lope', 'Fuenteovejuna (1612-1614)')]))
    P.append(dict(text='Quién mató al Comendador\nEl pasaje más recordado del tercer acto es el ensayo del interrogatorio. Esteban propone a los vecinos morir diciendo «Fuenteovejuna» y que nadie saque a nadie de allí; Frondoso responde: «Fuenteovejuna lo ha hecho». Para ensayar, Esteban hace de pesquisidor y Mengo de torturado: «¿Quién mató al comendador?» «Fuenteovejuna lo hizo.» Cuando le dicen que lo martirizarán, Mengo mantiene la respuesta. La unidad del pueblo es la clave del triunfo final, y ninguno delata al autor directo de las muertes. La fuente recoge la fórmula tradicional del diálogo: «¿Quién es Fuenteovejuna? —Todo el pueblo, a una». El pasaje mezcla tensión y humor, con la comicidad de Mengo, y da carácter coral a la rebelión.',
        quotes=[Q('ws_fuenteovejuna3', 'FRONDOSO: ¿Qué es tu consejo?', 'Fuenteovejuna lo ha hecho.'), Q('ws_fuenteovejuna3', 'ESTEBAN: ¿Quién mató al comendador?', 'MENGO: Fuenteovejuna lo hizo.'), Q('ws_fuenteovejuna3', 'ESTEBAN: Dadle otra vuelta.'), Q('es_fuenteovejuna', 'Todo el pueblo, a una.'), Q('es_fuenteovejuna', 'La clave de su triunfo final es la unidad de todo el pueblo.')]))
    P.append(dict(text='Tirso y el burlador\nTirso de Molina, seudónimo de fray Gabriel Téllez, fue un religioso mercedario que nació en Madrid en 1579 y destacó como dramaturgo del Barroco; discípulo fervoroso de Lope, defendió toda su vida la concepción lopista del teatro. Se le atribuye tradicionalmente El burlador de Sevilla, que recoge el mito de don Juan, y que se conserva en una publicación de 1630, con un precedente representado en Córdoba en 1617, Tan largo me lo fiais. Don Juan es un libertino que cree en la justicia divina, «no hay plazo que no se cumpla ni deuda que no se pague», pero confía en arrepentirse a tiempo. Su fortuna fue enorme: inspiró a Molière, Mozart, Espronceda y Zorrilla. La fuente subraya que Tirso fue el primero en dar profundidad psicológica a los personajes femeninos.',
        quotes=[Q('es_tirso', 'fue un religioso mercedario español que destacó como dramaturgo, poeta y narrador del Barroco'), Q('es_tirso', 'Tirso de Molina fue un discípulo fervoroso de Lope de Vega'), Q('es_burlador', 'que recoge el mito de don Juan, sin duda el personaje más universal del teatro español'), Q('es_burlador', 'no hay plazo que no se cumpla ni deuda que no se pague'), Q('es_tirso', 'Tirso fue el primer autor que dio profundidad psicológica a los personajes femeninos')]))
    P.append(dict(text='Calderón\nPedro Calderón de la Barca (Madrid, 1600-1681), caballero de Santiago, se ordenó sacerdote en 1651 y es uno de los más insignes literatos barrocos. Su teatro parte del de Lope, pero introduce modificaciones: suprime escenas innecesarias, reduce las secundarias y subordina los personajes a uno central. Su obra se divide en comedias religiosas, históricas, de enredo, de honor, filosóficas y autos sacramentales. La fuente añade que sus innovaciones se han llamado después metaficción y surrealismo, y que influyó en el romanticismo, el simbolismo y el modernismo; entre sus admiradores están Schlegel, Goethe y Borges.',
        quotes=[Q('es_calderon', 'Poeta cortesano y soldado, en 1651 se ordenó sacerdote.'), Q('es_calderon', 'suprime escenas innecesarias y reduce las secundarias; subordina los personajes a uno central'), Q('es_calderon', 'comedias religiosas (La devoción de la cruz), histórico-legendarias (El sitio de Breda)'), Q('es_calderon', 'Entre sus muchos admiradores se encuentran August Wilhelm von Schlegel, Johann Wolfgang von Goethe'), Q('en_golden_age', 'although the period is commonly understood to have continued in cultural terms until 1681')]))
    P.append(dict(text='La vida es sueño\nLa vida es sueño se estrenó en 1635 y su tema central es la libertad del hombre para configurar su vida, sin dejarse llevar por un supuesto destino. El influjo de la concepción platónica es evidente: Segismundo vive al principio en una cárcel que es una caverna, en oscuridad por el desconocimiento de sí mismo, y solo cuando sabe quién es consigue el triunfo, la luz. La obra puede leerse como drama religioso (caída y expiación), como poema filosófico (libre albedrío y predestinación), como lección moral del Barroco y la Contrarreforma que desengaña de las ilusiones del mundo, y como protesta contra la orden reservada que sofoca la libertad. Está dividida en tres jornadas que se desarrollan en la torre de Segismundo y en el palacio de Basilio.',
        quotes=[Q('es_vida_sueno', 'La vida es sueño es una obra de teatro de Pedro Calderón de la Barca estrenada en 1635'), Q('es_vida_sueno', 'El tema central es la libertad del ser humano para configurar su vida, sin dejarse llevar por un supuesto destino.'), Q('es_vida_sueno', 'Segismundo vive al principio dentro de una cárcel, de una caverna'), Q('es_vida_sueno', 'Como lección moral propia del barroco y la Contrarreforma, desengaña sobre las ilusiones y las vanidades de este mundo.'), Q('es_calderon', 'Su teatro, basado en el de Lope de Vega, introduce importantes modificaciones')]))
    P.append(dict(text='«¿Qué es la vida? Un frenesí»\nEl soliloquio de Segismundo cierra la segunda jornada con una reflexión sobre sí mismo: «Yo sueño que estoy aquí / destas prisiones cargado, / y soñé que en otro estado / más lisonjero me vi». La pregunta que lo remata es el centro del pensamiento barroco: «¿Qué es la vida? —Un frenesí. / ¿Qué es la vida? —Una ilusión, / una sombra, una ficción, / y el mayor bien es pequeño: / que toda la vida es sueño, / y los sueños sueño son». La fuente precisa que el soliloquio de la primera jornada está formado por siete décimas octosílabas y que la antítesis sostiene la dualidad entre civilización y barbarie. El de la segunda, que citamos, es el famoso por la serie de definiciones de la vida como ilusión y sombra.',
        quotes=[Q('ws_vida_sueno2', 'Yo sueño que estoy aquí', 'Mas lisonjero me vi.'), Q('ws_vida_sueno2', '¿Qué es la vida? — Un frenesí.', 'Y los sueños sueño son.'), Q('es_vida_sueno', 'El soliloquio de Segismundo en el primer acto está separado en siete décimas'), Q('es_vida_sueno', 'La representación de la civilización y la barbarie en Segismundo es la dualidad')]))
    P.append(dict(text='Góngora, de la luz a las tinieblas\nLuis de Góngora nació en Córdoba el 11 de julio de 1561 y murió allí el 23 de mayo de 1627; la fuente inglesa lo describe como poeta lírico barroco y sacerdote de la catedral de Córdoba. En una estancia en Valladolid, en 1603, se enemistó con Quevedo. Fue nombrado capellán real por Felipe III en 1617 y vivió en la Corte hasta 1626, arruinándose por conseguir cargos para sus familiares. No publicó sus obras: circularon en copias manuscritas, y el manuscrito más autorizado es el Manuscrito Chacón. La crítica, desde Menéndez Pelayo, distingue dos épocas: el «Príncipe de la Luz» de los romances y letrillas, y el «Príncipe de las Tinieblas» de la poesía oscura a partir de 1610.',
        quotes=[Q('es_gongora', 'Luis de Góngora y Argote (Córdoba, 11 de julio de 1561-Córdoba, 23 de mayo de 1627)'), Q('es_gongora', 'Felipe III le nombró capellán real en 1617'), Q('es_gongora', 'Aunque Góngora no publicó sus obras'), Q('es_gongora', 'el «Príncipe de la Luz»'), Q('en_gongora', 'was a Spanish Baroque lyric poet and a Catholic priest at Córdoba Cathedral')]))
    P.append(dict(text='Qué es el culteranismo\nEl culteranismo, o gongorismo, es una corriente del Barroco que se considera rama del conceptismo, con el que comparte la intención de intensificar la expresión y apartarla del equilibrio y la claridad clásica. Su nombre fue un término despectivo creado para señalar a los «cultos». Dámaso Alonso lo estudió en el tricentenario de Góngora y señaló sus rasgos: ornamentación sensorial (aliteraciones, epítetos), sintaxis de períodos largos y complejos, latinización de la sintaxis con hipérbaton violento, abuso de cultismos, metáfora pura y audaz, perífrasis y alusiones mitológicas. La fuente inglesa destaca que Góngora rescató palabras oscuras o poco usadas y las difundió; así contribuyó a la lengua.',
        quotes=[Q('es_culteranismo', 'El culteranismo es una corriente literaria del Barroco español.'), Q('es_culteranismo', 'Latinización de la sintaxis mediante un extremo y violento hipérbaton'), Q('es_culteranismo', 'Uso de la metáfora pura y de la imagen más audaz.'), Q('es_culteranismo', 'Preferencia por una sintaxis de largos y laberínticos periodos de compleja trabazón hipotáctica.'), Q('en_gongora', 'His style is characterized by what was called culteranismo, also known as Gongorismo.')]))
    P.append(dict(text='Polifemo y Soledades\nLos poemas mayores de Góngora son la Fábula de Polifemo y Galatea (1612), en octavas reales, que cuenta un episodio de las Metamorfosis de Ovidio, y las Soledades, escritas antes de mayo de 1613 en silvas. Las Soledades iban a ser un poema en cuatro partes, cada una correspondiente a una edad de la vida humana y a una estación del año (de los campos, de las riberas, de las selvas y del yermo), pero Góngora solo compuso la dedicatoria al duque de Béjar y las dos primeras. Estas obras ocasionaron la «revolución culterana» y un escándalo por su gran oscuridad. La fuente inglesa los llama «the two landmark works» del estilo culterano.',
        quotes=[Q('es_gongora', 'Son la Fábula de Polifemo y Galatea (1612)'), Q('es_gongora', 'Las Soledades iba a ser un poema en silvas, dividido en cuatro partes'), Q('es_gongora', 'Pero Góngora solo compuso la dedicatoria al duque de Béjar y las dos primeras'), Q('en_gongora', 'the two landmark works of the highly refined style called "culteranismo" or "Gongorismo"')]))
    P.append(dict(text='Un soneto sobre la belleza efímera\n«Mientras por competir con tu cabello» es uno de los sonetos más conocidos de Góngora, y recoge el tópico del carpe diem que ya había usado Garcilaso en el soneto XXIII. Los dos cuartetos construyen una larga subordinada temporal con una serie de comparaciones: el oro bruñido relumbra en vano ante el cabello; el lirio mira con menosprecio la frente blanca; los ojos siguen cada labio más que al clavel; y el cuello triunfa del cristal. En el primer terceto llega la orden: «goza cuello, cabello, labio, y frente». El último verso lleva la imagen hasta el límite: todo se convertirá «en tierra, en humo, en polvo, en sombra, en nada». Hay que notar la enumeración final, el estilo culterano y el desengaño barroco que sustituye la mesura renacentista.',
        quotes=[Q('ws_gongora_mientras', 'Mientras por competir con tu cabello', 'mira tu blanca frente el lilio bello;'), Q('ws_gongora_mientras', 'goza cuello, cabello, labio, y frente,'), Q('ws_gongora_mientras', 'en tierra, en humo, en polvo, en sombra, en nada.'), Q('es_gongora', 'Entre los tópicos usuales (carpe diem, etc.)')]))
    P.append(dict(text='Quevedo\nFrancisco de Quevedo nació en Madrid el 14 de septiembre de 1580 y murió en Villanueva de los Infantes el 8 de septiembre de 1645; fue caballero de Santiago desde 1618 y señor de Torre de Juan Abad. Nació cojo y con miopía severa. Su obra poética consta de unos 875 poemas de casi todos los subgéneros de su época: satírico-burlesca, amorosa, moral, fúnebre, religiosa y filosófica. La primera impresión de sus poemas fue en 1605; la mayoría se publicó póstumamente en El Parnaso español (1648) y Las tres musas últimas castellanas (1670). La poesía amorosa, la más importante del siglo XVII, es la más paradójica: concibe el amor como un ideal inalcanzable, una lucha de contrarios.',
        quotes=[Q('es_quevedo', 'Francisco Gómez de Quevedo Villegas y Santibáñez Cevallos (Madrid, 14 de septiembre de 1580'), Q('es_quevedo', 'Nació cojo, con ambas piernas torcidas y una severa miopía'), Q('es_quevedo', 'está constituida por unos 875 poemas'), Q('es_quevedo', 'La poesía amorosa de Quevedo, considerada la más importante del siglo XVII'), Q('en_quevedo', 'was a Spanish nobleman, politician and writer of the Baroque era')]))
    P.append(dict(text='Concepto y agudeza\nEl conceptismo es una corriente que se funda en una asociación ingeniosa entre palabras e ideas llamadas «concepto» o «agudeza». Baltasar Gracián, su máximo teórico, define el concepto como «un acto del entendimiento que expresa la correspondencia que se halla entre los objetos». Busca la concisión exacta, la mayor cantidad de significado en las menos palabras posibles, con recursos como la elipsis, el zeugma, la anfibología, la antítesis, el equívoco, la paradoja o la paronomasia. A diferencia del culteranismo, que prefiere el verso y amplifica un mínimo de pensamiento, el conceptismo prefiere la prosa. Quevedo es su representante más conocido; la fuente inglesa dice que su estilo es el conceptismo.',
        quotes=[Q('es_conceptismo', 'se funda en una asociación ingeniosa entre palabras e ideas denominadas «concepto» o «agudeza»'), Q('es_conceptismo', '«Un acto del entendimiento que expresa la correspondencia que se halla entre los objetos»'), Q('es_conceptismo', 'Sus recursos formales más usuales son la elipsis, el zeugma, la anfibología y polisemia, la antítesis'), Q('en_quevedo', 'His style is characterized by what was called conceptismo.')]))
    P.append(dict(text='Polvo enamorado\nEl soneto «Amor constante más allá de la muerte» es la cumbre de la poesía amorosa de Quevedo. Los cuartetos dicen que la última sombra podrá cerrar sus ojos y desatar su alma, pero no la memoria: «nadar sabe mi llama la agua fría». Los tercetos lo repiten con una serie de sustantivos (alma, venas, médulas) y un remate de máxima tensión conceptista: «serán ceniza, mas tendrá sentido; / polvo serán, mas polvo enamorado». La fuente en español explica que Quevedo une amor y muerte, los dos temas del Canzoniere de Petrarca, en uno solo. La paradoja («polvo» y «enamorado») y la antítesis (ceniza/sentido) son los recursos del conceptismo.',
        quotes=[Q('ws_quevedo_constante', 'Cerrar podrá mis ojos la postrera', 'hora a su afán ansioso lisonjera;'), Q('ws_quevedo_constante', 'nadar sabe mi llama la agua fría,'), Q('ws_quevedo_constante', 'serán ceniza, mas tendrá sentido;', 'polvo serán, mas polvo enamorado.'), Q('es_quevedo', 'Quevedo une el amor y la muerte, los temas de las dos partes del Canzoniere de Francesco Petrarca, en uno solo')]))
    P.append(dict(text='Desengaño\n«Miré los muros de la patria mía» pertenece al Heráclito cristiano, terminado en 1613 tras una crisis espiritual y publicado en 1670 con el título de Lágrimas de un penitente. El soneto recorre la ruina de las murallas, el campo, la casa y su propio cuerpo: «mi báculo más corvo y menos fuerte»; y concluye que no halló cosa en que poner los ojos «que no fuese recuerdo de la muerte». Es una meditación sobre el paso del tiempo y la caducidad, la misma sobre la que había escrito Manrique, pero con la visión ascética y amarga del Barroco. El poema es un buen ejemplo del desengaño, la actitud con la que la literatura barroca responde a la crisis política y moral de la monarquía.',
        quotes=[Q('ws_quevedo_muros', 'Miré los muros de la patria mía,', 'por quien caduca ya su valentía.'), Q('ws_quevedo_muros', 'que no fuese recuerdo de la muerte.'), Q('es_quevedo', 'incluye el famoso soneto "Miré los muros de la Patria mía"'), Q('es_quevedo', 'En 1613 terminó, pero no publicó su Heráclito cristiano')]))
    P.append(dict(text='Dos estéticas enfrentadas\nLa rivalidad entre Góngora y Quevedo, que según las dos fuentes fue de por vida, es también un debate estético. Quevedo se burló del lenguaje culterano en la Aguja de navegar cultos, una sátira en prosa (la fuente inglesa la llama soneto), que enumera palabras del léxico de Góngora; Góngora le acusó de imitar su poesía satírica. La fuente inglesa los considera, juntos, los poetas españoles más destacados de todos los tiempos. La diferencia: el culteranismo dificulta la comprensión mediante largos períodos latinizantes; el conceptismo, mediante la concentración extrema de sentido. Aun así las fuentes advierten que ambas corrientes confluyen y que tienen en común la intención de intensificar la expresión.',
        quotes=[Q('es_gongora', 'se enemistó con Francisco de Quevedo, a quien acusó de imitar su poesía satírica bajo pseudónimo'), Q('en_quevedo', 'Quevedo lampooned his rival by writing a sonnet, Aguja de navegar cultos'), Q('en_gongora', 'Góngora and his lifelong rival, Francisco de Quevedo, are widely considered the most prominent Spanish poets of all time.'), Q('es_conceptismo', 'el conceptismo llegó a confluir al fin con el culteranismo')]))
    return P


